  'co.estimateManual': { en: 'processed manually. Account sent to your email once done.', zh: '手动处理。完成后账户将发送到您的邮箱。', ja: '手動で処理されます。完了後にアカウントがメールに送信されます。', id: 'diproses manual. Akun dikirim ke emailmu setelah selesai.', ru: 'обрабатывается вручную. Аккаунт придёт на email после готовности.', ms: 'diproses secara manual. Akaun dihantar ke e-mel anda selepas siap.', hi: 'मैन्युअल रूप से संसाधित। पूरा होने पर खाता आपके ईमेल पर।', de: 'wird manuell bearbeitet. Konto wird nach Fertigstellung gesendet.', vi: 'xử lý thủ công. Tài khoản gửi đến email sau khi hoàn tất.' },
  'co.actTitle': { en: 'ACTIVATION METHOD', zh: '激活方式', ja: 'アクティベーション方法', id: 'METODE AKTIVASI', ru: 'СПОСОБ АКТИВАЦИИ', ms: 'KAEDAH PENGAKTIFAN', hi: 'सक्रियण विधि', de: 'AKTIVIERUNGSMETHODE', vi: 'PHƯƠNG THỨC KÍCH HOẠT' },
  'co.actSub': { en: 'Choose a new account from us, or use your own account to be upgraded.', zh: '选择我们提供的新账户，或使用您自己的账户进行升级。', ja: '当社の新規アカウント、またはご自身のアカウントをアップグレードしてご利用ください。', id: 'Pilih akun baru dari kami, atau pakai akun milikmu sendiri untuk di-upgrade.', ru: 'Выберите новый аккаунт от нас или используйте свой для апгрейда.', ms: 'Pilih akaun baharu daripada kami, atau guna akaun anda untuk dinaik taraf.', hi: 'हमारा नया खाता चुनें, या अपना खाता अपग्रेड के लिए उपयोग करें।', de: 'Wählen Sie ein neues Konto von uns oder Ihr eigenes zum Upgrade.', vi: 'Chọn tài khoản mới từ chúng tôi, hoặc dùng tài khoản của bạn để nâng cấp.' },
