  'co.actNewDesc': { en: 'We prepare a new account & send it to your email.', zh: '我们会准备一个新账户并发送到您的邮箱。', ja: '新しいアカウントを用意してメールに送信します。', id: 'Kami siapkan akun baru & kirim ke email kamu.', ru: 'Мы готовим новый аккаунт и отправляем на email.', ms: 'Kami sediakan akaun baharu & hantar ke e-mel anda.', hi: 'हम नया खाता तैयार कर आपके ईमेल पर भेजते हैं।', de: 'Wir erstellen ein neues Konto & senden es an Ihre E-Mail.', vi: 'Chúng tôi tạo tài khoản mới & gửi đến email bạn.' },
