  'rev.buyText': { en: 'Rating is locked. Only verified buyers can write reviews — complete a purchase and rating unlocks automatically.', zh: '评分已锁定。只有已验证的买家才能撰写评价 — 完成购买后评分将自动解锁。', ja: '評価はロックされています。認証済みの購入者のみレビューを書けます — 購入を完了すると自動的に解除されます。', id: 'Rating dikunci. Hanya pembeli terverifikasi yang bisa menulis ulasan — selesaikan pembelian dulu, lalu rating terbuka otomatis.', ru: 'Оценка заблокирована. Отзывы могут писать только проверенные покупатели — после покупки оценка откроется автоматически.', ms: 'Penilaian dikunci. Hanya pembeli disahkan boleh menulis ulasan — selesaikan pembelian dan penilaian terbuka automatik.', hi: 'रेटिंग लॉक है। केवल सत्यापित खरीदार समीक्षा लिख सकते हैं — खरीद पूरी करें, रेटिंग स्वतः खुल जाएगी।', de: 'Bewertung gesperrt. Nur verifizierte Käufer können bewerten — nach dem Kauf wird sie automatisch freigeschaltet.', vi: 'Đánh giá bị khóa. Chỉ người mua đã xác minh mới viết được — hoàn tất mua hàng, đánh giá sẽ tự mở.' },
  'rev.buyFirst': { en: 'Buy First', zh: '先购买', ja: 'まず購入', id: 'Beli Dulu', ru: 'Сначала купить', ms: 'Beli Dahulu', hi: 'पहले खरीदें', de: 'Zuerst kaufen', vi: 'Mua trước' },
  'rev.verifiedBuyer': { en: 'Verified Buyer', zh: '已验证买家', ja: '認証済み購入者', id: 'Pembeli Terverifikasi', ru: 'Проверенный покупатель', ms: 'Pembeli Disahkan', hi: 'सत्यापित खरीदार', de: 'Verifizierter Käufer', vi: 'Người mua đã xác minh' },
  'rev.updatable': { en: '· You already rated, you can update it', zh: '· 您已评价，可更新', ja: '· 既に評価済み、更新できます', id: '· Kamu sudah pernah menilai, bisa diperbarui', ru: '· Вы уже оценили, можно обновить', ms: '· Anda sudah menilai, boleh dikemas kini', hi: '· आपने रेट किया है, अपडेट कर सकते हैं', de: '· Bereits bewertet, aktualisierbar', vi: '· Bạn đã đánh giá, có thể cập nhật' },
  'rev.giveRating': { en: 'Give a Rating', zh: '给出评分', ja: '評価する', id: 'Beri Rating', ru: 'Поставьте оценку', ms: 'Beri Penilaian', hi: 'रेटिंग दें', de: 'Bewertung abgeben', vi: 'Đánh giá' },
  'rev.commentPlaceholder': { en: 'Share your experience (optional)…', zh: '分享您的体验（可选）…', ja: '体験を共有（任意）…', id: 'Bagikan pengalamanmu (opsional)…', ru: 'Поделитесь впечатлением (необязательно)…', ms: 'Kongsi pengalaman anda (pilihan)…', hi: 'अपना अनुभव साझा करें (वैकल्पिक)…', de: 'Teilen Sie Ihre Erfahrung (optional)…', vi: 'Chia sẻ trải nghiệm (tùy chọn)…' },
  'rev.saved': { en: 'Saved', zh: '已保存', ja: '保存しました', id: 'Tersimpan', ru: 'Сохранено', ms: 'Disimpan', hi: 'सहेजा गया', de: 'Gespeichert', vi: 'Đã lưu' },
  'rev.update': { en: 'Update Review', zh: '更新评价', ja: 'レビューを更新', id: 'Perbarui Ulasan', ru: 'Обновить отзыв', ms: 'Kemas Kini Ulasan', hi: 'समीक्षा अपडेट करें', de: 'Bewertung aktualisieren', vi: 'Cập nhật đánh giá' },
  'rev.submit': { en: 'Submit Review', zh: '提交评价', ja: 'レビューを送信', id: 'Kirim Ulasan', ru: 'Отправить отзыв', ms: 'Hantar Ulasan', hi: 'समीक्षा भेजें', de: 'Bewertung senden', vi: 'Gửi đánh giá' },
  'rev.verified': { en: 'Verified', zh: '已验证', ja: '認証済み', id: 'Terverifikasi', ru: 'Проверено', ms: 'Disahkan', hi: 'सत्यापित', de: 'Verifiziert', vi: 'Đã xác minh' },
  'rev.pickStars': { en: 'Pick a star rating first.', zh: '请先选择星级。', ja: '先に星評価を選んでください。', id: 'Pilih jumlah bintang dulu.', ru: 'Сначала выберите количество звёзд.', ms: 'Pilih bilangan bintang dahulu.', hi: 'पहले स्टार रेटिंग चुनें।', de: 'Wählen Sie zuerst eine Sternebewertung.', vi: 'Chọn số sao trước.' },
  'rev.submitFail': { en: 'Failed to submit review.', zh: '提交评价失败。', ja: 'レビューの送信に失敗しました。', id: 'Gagal mengirim ulasan.', ru: 'Не удалось отправить отзыв.', ms: 'Gagal menghantar ulasan.', hi: 'समीक्षा भेजने में विफल।', de: 'Bewertung konnte nicht gesendet werden.', vi: 'Gửi đánh giá thất bại.' },
  'rev.showAll': { en: 'Show All Reviews', zh: '查看所有评价', ja: 'すべてのレビューを見る', id: 'Lihat Semua Ulasan', ru: 'Все отзывы', ms: 'Lihat Semua Ulasan', hi: 'सभी समीक्षाएं देखें', de: 'Alle Bewertungen', vi: 'Xem tất cả đánh giá' },
