  'home.benefit1Desc': { en: 'Accounts delivered automatically within minutes after payment.', zh: '付款后几分钟内自动交付账户。', ja: '支払い後数分でアカウントを自動配信。', id: 'Akun dikirim otomatis dalam hitungan menit setelah pembayaran.', ru: 'Аккаунты выдаются автоматически за пару минут после оплаты.', ms: 'Akaun dihantar automatik dalam beberapa minit selepas bayaran.', hi: 'भुगतान के मिनटों में खाते स्वतः वितरित।', de: 'Konten werden Minuten nach der Zahlung automatisch geliefert.', vi: 'Tài khoản giao tự động trong vài phút sau khi thanh toán.' },
  'home.benefit2Title': { en: 'Full Warranty', zh: '全面保障', ja: '完全保証', id: 'Garansi Penuh', ru: 'Полная гарантия', ms: 'Jaminan Penuh', hi: 'पूर्ण वारंटी', de: 'Volle Garantie', vi: 'Bảo hành đầy đủ' },
  'home.benefit2Desc': { en: 'Every product is warranted for the entire subscription period.', zh: '每件产品在整个订阅期内享受保障。', ja: '全製品がサブスク期間中ずっと保証されます。', id: 'Setiap produk bergaransi selama masa aktif langganan.', ru: 'Каждый товар на гарантии весь срок подписки.', ms: 'Setiap produk dijamin sepanjang tempoh langganan.', hi: 'हर उत्पाद पूरी सदस्यता अवधि के लिए वारंटीड।', de: 'Jedes Produkt ist für die gesamte Abolaufzeit garantiert.', vi: 'Mọi sản phẩm được bảo hành suốt thời gian đăng ký.' },
  'home.benefit3Title': { en: 'Legal Accounts', zh: '合法账户', ja: '正規アカウント', id: 'Akun Legal', ru: 'Легальные аккаунты', ms: 'Akaun Sah', hi: 'वैध खाते', de: 'Legale Konten', vi: 'Tài khoản hợp pháp' },
  'home.benefit3Desc': { en: 'All products are official and verified, not pirated accounts.', zh: '所有产品均为官方且已验证，非盗版账户。', ja: 'すべて公式・認証済みで、海賊版アカウントではありません。', id: 'Semua produk resmi dan terverifikasi, bukan akun bajakan.', ru: 'Все товары официальные и проверенные, не пиратские.', ms: 'Semua produk rasmi dan disahkan, bukan akaun cetak rompak.', hi: 'सभी उत्पाद आधिकारिक व सत्यापित, पायरेटेड नहीं।', de: 'Alle Produkte sind offiziell und verifiziert, keine Raubkopien.', vi: 'Mọi sản phẩm chính thức và đã xác minh, không phải tài khoản lậu.' },
  'home.benefit4Title': { en: 'Support 24/7', zh: '全天候支持', ja: '24時間サポート', id: 'Support 24/7', ru: 'Поддержка 24/7', ms: 'Sokongan 24/7', hi: 'सहायता 24/7', de: 'Support 24/7', vi: 'Hỗ trợ 24/7' },
  'home.benefit4Desc': { en: 'Our team is ready to help anytime via live chat.', zh: '我们的团队随时通过在线聊天提供帮助。', ja: 'チームがライブチャットでいつでもサポートします。', id: 'Tim kami siap membantu kapan pun lewat chat langsung.', ru: 'Наша команда поможет в любое время в чате.', ms: 'Pasukan kami sedia membantu bila-bila melalui sembang langsung.', hi: 'हमारी टीम लाइव चैट से कभी भी मदद के लिए तैयार।', de: 'Unser Team hilft jederzeit per Live-Chat.', vi: 'Đội ngũ sẵn sàng hỗ trợ mọi lúc qua chat trực tiếp.' },
