  'home.ctaTitle': { en: 'BOOST YOUR PRODUCTIVITY WITH TRUSTED PREMIUM ACCOUNTS', zh: '用值得信赖的高级账户提升您的生产力', ja: '信頼できるプレミアムアカウントで生産性を向上', id: 'UPGRADE PRODUKTIVITASMU DENGAN AKUN PREMIUM TERPERCAYA', ru: 'ПОВЫСЬТЕ ПРОДУКТИВНОСТЬ С НАДЁЖНЫМИ ПРЕМИУМ-АККАУНТАМИ', ms: 'TINGKATKAN PRODUKTIVITI ANDA DENGAN AKAUN PREMIUM DIPERCAYAI', hi: 'विश्वसनीय प्रीमियम खातों से अपनी उत्पादकता बढ़ाएं', de: 'STEIGERN SIE IHRE PRODUKTIVITÄT MIT VERTRAUENSWÜRDIGEN PREMIUM-KONTEN', vi: 'TĂNG NĂNG SUẤT VỚI TÀI KHOẢN CAO CẤP ĐÁNG TIN CẬY' },
  'home.ctaText': { en: 'Thousands of customers already trust Upbit Store for their digital needs. Now it’s your turn.', zh: '数千名客户已信赖 Upbit Store 满足他们的数字需求。现在轮到您了。', ja: '何千ものお客様がデジタルニーズで Upbit Store を信頼しています。次はあなたの番です。', id: 'Ribuan pelanggan sudah mempercayakan kebutuhan digital mereka pada Upbit Store. Giliranmu sekarang.', ru: 'Тысячи клиентов уже доверяют Upbit Store свои цифровые нужды. Теперь ваша очередь.', ms: 'Ribuan pelanggan sudah mempercayai Upbit Store untuk keperluan digital mereka. Kini giliran anda.', hi: 'हजारों ग्राहक अपनी डिजिटल जरूरतों के लिए Upbit Store पर भरोसा करते हैं। अब आपकी बारी।', de: 'Tausende Kunden vertrauen Upbit Store bereits für ihre digitalen Bedürfnisse. Jetzt sind Sie dran.', vi: 'Hàng nghìn khách hàng đã tin tưởng Upbit Store cho nhu cầu số. Giờ đến lượt bạn.' },
  'home.ctaBtn': { en: 'Explore Catalog', zh: '浏览目录', ja: 'カタログを見る', id: 'Jelajahi Katalog', ru: 'Открыть каталог', ms: 'Terokai Katalog', hi: 'कैटलॉग देखें', de: 'Katalog entdecken', vi: 'Khám phá danh mục' },
